(function (global) {
    const CONFIG = {
        1: { ecc: 7, blocks: [19], align: [] },
        2: { ecc: 10, blocks: [34], align: [6, 18] },
        3: { ecc: 15, blocks: [55], align: [6, 22] },
        4: { ecc: 20, blocks: [80], align: [6, 26] },
        5: { ecc: 26, blocks: [108], align: [6, 30] },
        6: { ecc: 18, blocks: [68, 68], align: [6, 34] },
        7: { ecc: 20, blocks: [78, 78], align: [6, 22, 38] },
        8: { ecc: 24, blocks: [97, 97], align: [6, 24, 42] },
        9: { ecc: 30, blocks: [116, 116], align: [6, 26, 46] },
        10: { ecc: 18, blocks: [68, 68, 69, 69], align: [6, 28, 50] }
    };

    const EXP = new Array(512);
    const LOG = new Array(256);

    (function initGalois() {
        let x = 1;

        for (let i = 0; i < 255; i++) {
            EXP[i] = x;
            LOG[x] = i;
            x <<= 1;

            if (x & 0x100) {
                x ^= 0x11d;
            }
        }

        for (let i = 255; i < EXP.length; i++) {
            EXP[i] = EXP[i - 255];
        }
    })();

    function gfMul(a, b) {
        if (a === 0 || b === 0) {
            return 0;
        }

        return EXP[LOG[a] + LOG[b]];
    }

    function generatorPoly(degree) {
        let poly = [1];

        for (let i = 0; i < degree; i++) {
            const next = new Array(poly.length + 1).fill(0);

            for (let j = 0; j < poly.length; j++) {
                next[j] ^= poly[j];
                next[j + 1] ^= gfMul(poly[j], EXP[i]);
            }

            poly = next;
        }

        return poly;
    }

    function reedSolomon(data, degree) {
        const gen = generatorPoly(degree);
        const rem = new Array(degree).fill(0);

        data.forEach(function (byte) {
            const factor = byte ^ rem.shift();
            rem.push(0);

            for (let i = 0; i < degree; i++) {
                rem[i] ^= gfMul(gen[i + 1], factor);
            }
        });

        return rem;
    }

    function pushBits(bits, value, length) {
        for (let i = length - 1; i >= 0; i--) {
            bits.push((value >>> i) & 1);
        }
    }

    function bytesFromText(text) {
        return Array.from(new TextEncoder().encode(text));
    }

    function chooseVersion(dataLength) {
        for (let version = 1; version <= 10; version++) {
            const dataBytes = CONFIG[version].blocks.reduce((sum, block) => sum + block, 0);
            const countBits = version < 10 ? 8 : 16;
            const requiredBits = 4 + countBits + dataLength * 8;

            if (requiredBits <= dataBytes * 8) {
                return version;
            }
        }

        throw new Error("Texto muito grande para este gerador de QR Code.");
    }

    function buildDataCodewords(text, version) {
        const bytes = bytesFromText(text);
        const dataBytes = CONFIG[version].blocks.reduce((sum, block) => sum + block, 0);
        const capacityBits = dataBytes * 8;
        const countBits = version < 10 ? 8 : 16;
        const bits = [];

        pushBits(bits, 0x4, 4);
        pushBits(bits, bytes.length, countBits);

        bytes.forEach(function (byte) {
            pushBits(bits, byte, 8);
        });

        const terminator = Math.min(4, capacityBits - bits.length);
        pushBits(bits, 0, terminator);

        while (bits.length % 8 !== 0) {
            bits.push(0);
        }

        const codewords = [];

        for (let i = 0; i < bits.length; i += 8) {
            codewords.push(bits.slice(i, i + 8).reduce((value, bit) => (value << 1) | bit, 0));
        }

        let pad = 0xec;

        while (codewords.length < dataBytes) {
            codewords.push(pad);
            pad = pad === 0xec ? 0x11 : 0xec;
        }

        return codewords;
    }

    function interleaveBlocks(dataCodewords, version) {
        const config = CONFIG[version];
        const dataBlocks = [];
        let offset = 0;

        config.blocks.forEach(function (length) {
            const block = dataCodewords.slice(offset, offset + length);
            offset += length;
            dataBlocks.push(block);
        });

        const eccBlocks = dataBlocks.map(block => reedSolomon(block, config.ecc));
        const result = [];
        const maxData = Math.max(...dataBlocks.map(block => block.length));

        for (let i = 0; i < maxData; i++) {
            dataBlocks.forEach(function (block) {
                if (i < block.length) {
                    result.push(block[i]);
                }
            });
        }

        for (let i = 0; i < config.ecc; i++) {
            eccBlocks.forEach(function (block) {
                result.push(block[i]);
            });
        }

        return result;
    }

    function emptyMatrix(size) {
        return {
            modules: Array.from({ length: size }, () => new Array(size).fill(false)),
            func: Array.from({ length: size }, () => new Array(size).fill(false))
        };
    }

    function setModule(matrix, x, y, value, isFunction) {
        if (x < 0 || y < 0 || y >= matrix.modules.length || x >= matrix.modules.length) {
            return;
        }

        matrix.modules[y][x] = Boolean(value);

        if (isFunction) {
            matrix.func[y][x] = true;
        }
    }

    function drawFinder(matrix, x, y) {
        for (let dy = -1; dy <= 7; dy++) {
            for (let dx = -1; dx <= 7; dx++) {
                const xx = x + dx;
                const yy = y + dy;
                const inside = dx >= 0 && dx <= 6 && dy >= 0 && dy <= 6;
                const black = inside && (dx === 0 || dx === 6 || dy === 0 || dy === 6 || (dx >= 2 && dx <= 4 && dy >= 2 && dy <= 4));
                setModule(matrix, xx, yy, black, true);
            }
        }
    }

    function drawAlignment(matrix, cx, cy) {
        for (let dy = -2; dy <= 2; dy++) {
            for (let dx = -2; dx <= 2; dx++) {
                const distance = Math.max(Math.abs(dx), Math.abs(dy));
                setModule(matrix, cx + dx, cy + dy, distance !== 1, true);
            }
        }
    }

    function drawPatterns(matrix, version) {
        const size = matrix.modules.length;
        drawFinder(matrix, 0, 0);
        drawFinder(matrix, size - 7, 0);
        drawFinder(matrix, 0, size - 7);

        for (let i = 8; i < size - 8; i++) {
            setModule(matrix, i, 6, i % 2 === 0, true);
            setModule(matrix, 6, i, i % 2 === 0, true);
        }

        CONFIG[version].align.forEach(function (cx) {
            CONFIG[version].align.forEach(function (cy) {
                const overlapsFinder = (cx <= 8 && cy <= 8) || (cx >= size - 9 && cy <= 8) || (cx <= 8 && cy >= size - 9);

                if (!overlapsFinder) {
                    drawAlignment(matrix, cx, cy);
                }
            });
        });

        setModule(matrix, 8, size - 8, true, true);
        drawFormatBits(matrix, 0);
    }

    function maskBit(mask, x, y) {
        switch (mask) {
            case 0: return (x + y) % 2 === 0;
            case 1: return y % 2 === 0;
            case 2: return x % 3 === 0;
            case 3: return (x + y) % 3 === 0;
            case 4: return (Math.floor(y / 2) + Math.floor(x / 3)) % 2 === 0;
            case 5: return ((x * y) % 2 + (x * y) % 3) === 0;
            case 6: return (((x * y) % 2 + (x * y) % 3) % 2) === 0;
            default: return (((x + y) % 2 + (x * y) % 3) % 2) === 0;
        }
    }

    function formatBits(mask) {
        let data = (1 << 3) | mask;
        let rem = data;

        for (let i = 0; i < 10; i++) {
            rem = (rem << 1) ^ (((rem >>> 9) & 1) * 0x537);
        }

        return ((data << 10) | rem) ^ 0x5412;
    }

    function drawFormatBits(matrix, mask) {
        const size = matrix.modules.length;
        const bits = formatBits(mask);
        const bit = i => ((bits >>> i) & 1) === 1;

        for (let i = 0; i <= 5; i++) {
            setModule(matrix, 8, i, bit(i), true);
        }

        setModule(matrix, 8, 7, bit(6), true);
        setModule(matrix, 8, 8, bit(7), true);
        setModule(matrix, 7, 8, bit(8), true);

        for (let i = 9; i < 15; i++) {
            setModule(matrix, 14 - i, 8, bit(i), true);
        }

        for (let i = 0; i < 8; i++) {
            setModule(matrix, size - 1 - i, 8, bit(i), true);
        }

        for (let i = 8; i < 15; i++) {
            setModule(matrix, 8, size - 15 + i, bit(i), true);
        }
    }

    function placeData(matrix, codewords) {
        const size = matrix.modules.length;
        const bits = [];

        codewords.forEach(function (byte) {
            pushBits(bits, byte, 8);
        });

        let bitIndex = 0;
        let upward = true;

        for (let right = size - 1; right >= 1; right -= 2) {
            if (right === 6) {
                right--;
            }

            for (let vert = 0; vert < size; vert++) {
                const y = upward ? size - 1 - vert : vert;

                for (let dx = 0; dx < 2; dx++) {
                    const x = right - dx;

                    if (!matrix.func[y][x]) {
                        matrix.modules[y][x] = bitIndex < bits.length ? bits[bitIndex] === 1 : false;
                        bitIndex++;
                    }
                }
            }

            upward = !upward;
        }
    }

    function cloneMatrix(matrix) {
        return {
            modules: matrix.modules.map(row => row.slice()),
            func: matrix.func.map(row => row.slice())
        };
    }

    function applyMask(matrix, mask) {
        const size = matrix.modules.length;

        for (let y = 0; y < size; y++) {
            for (let x = 0; x < size; x++) {
                if (!matrix.func[y][x] && maskBit(mask, x, y)) {
                    matrix.modules[y][x] = !matrix.modules[y][x];
                }
            }
        }

        drawFormatBits(matrix, mask);
    }

    function penalty(matrix) {
        const m = matrix.modules;
        const size = m.length;
        let score = 0;

        for (let y = 0; y < size; y++) {
            let runColor = m[y][0];
            let run = 1;

            for (let x = 1; x < size; x++) {
                if (m[y][x] === runColor) {
                    run++;
                } else {
                    if (run >= 5) {
                        score += 3 + run - 5;
                    }

                    runColor = m[y][x];
                    run = 1;
                }
            }

            if (run >= 5) {
                score += 3 + run - 5;
            }
        }

        for (let x = 0; x < size; x++) {
            let runColor = m[0][x];
            let run = 1;

            for (let y = 1; y < size; y++) {
                if (m[y][x] === runColor) {
                    run++;
                } else {
                    if (run >= 5) {
                        score += 3 + run - 5;
                    }

                    runColor = m[y][x];
                    run = 1;
                }
            }

            if (run >= 5) {
                score += 3 + run - 5;
            }
        }

        for (let y = 0; y < size - 1; y++) {
            for (let x = 0; x < size - 1; x++) {
                const color = m[y][x];

                if (m[y][x + 1] === color && m[y + 1][x] === color && m[y + 1][x + 1] === color) {
                    score += 3;
                }
            }
        }

        const pattern = [true, false, true, true, true, false, true, false, false, false, false];

        function hasPattern(line, i) {
            for (let j = 0; j < pattern.length; j++) {
                if (line[i + j] !== pattern[j]) {
                    return false;
                }
            }

            return true;
        }

        for (let y = 0; y < size; y++) {
            for (let x = 0; x <= size - pattern.length; x++) {
                if (hasPattern(m[y], x) || hasPattern(m[y].slice().reverse(), size - pattern.length - x)) {
                    score += 40;
                }
            }
        }

        for (let x = 0; x < size; x++) {
            const col = m.map(row => row[x]);

            for (let y = 0; y <= size - pattern.length; y++) {
                if (hasPattern(col, y) || hasPattern(col.slice().reverse(), size - pattern.length - y)) {
                    score += 40;
                }
            }
        }

        const dark = m.flat().filter(Boolean).length;
        const percent = dark * 100 / (size * size);
        score += Math.floor(Math.abs(percent - 50) / 5) * 10;

        return score;
    }

    function makeMatrix(text) {
        const bytes = bytesFromText(text);
        const version = chooseVersion(bytes.length);
        const size = 21 + (version - 1) * 4;
        const data = buildDataCodewords(text, version);
        const codewords = interleaveBlocks(data, version);
        const base = emptyMatrix(size);
        drawPatterns(base, version);
        placeData(base, codewords);

        let best = null;
        let bestScore = Infinity;

        for (let mask = 0; mask < 8; mask++) {
            const candidate = cloneMatrix(base);
            applyMask(candidate, mask);
            const score = penalty(candidate);

            if (score < bestScore) {
                bestScore = score;
                best = candidate.modules;
            }
        }

        return best;
    }

    function render(element, matrix, options) {
        const width = options.width || 180;
        const height = options.height || width;
        const quiet = 4;
        const size = matrix.length;
        const canvas = document.createElement("canvas");
        canvas.width = width;
        canvas.height = height;

        const ctx = canvas.getContext("2d");
        ctx.fillStyle = "#ffffff";
        ctx.fillRect(0, 0, width, height);

        const scale = Math.floor(Math.min(width, height) / (size + quiet * 2)) || 1;
        const total = (size + quiet * 2) * scale;
        const offsetX = Math.floor((width - total) / 2) + quiet * scale;
        const offsetY = Math.floor((height - total) / 2) + quiet * scale;

        ctx.fillStyle = options.colorDark || "#111827";

        for (let y = 0; y < size; y++) {
            for (let x = 0; x < size; x++) {
                if (matrix[y][x]) {
                    ctx.fillRect(offsetX + x * scale, offsetY + y * scale, scale, scale);
                }
            }
        }

        element.innerHTML = "";
        element.appendChild(canvas);
    }

    function QRCode(element, options) {
        const target = typeof element === "string" ? document.getElementById(element) : element;

        if (!target) {
            throw new Error("Elemento do QR Code não encontrado.");
        }

        this.element = target;
        this.options = Object.assign({ width: 180, height: 180 }, options || {});

        if (this.options.text) {
            this.makeCode(this.options.text);
        }
    }

    QRCode.prototype.makeCode = function (text) {
        render(this.element, makeMatrix(text), Object.assign({}, this.options, { text }));
    };

    QRCode.prototype.clear = function () {
        this.element.innerHTML = "";
    };

    global.QRCode = QRCode;
})(window);
